/**
 * Regenerates CHANGELOG.md from conventional commit messages.
 *
 *   npm run changelog
 *
 * Sections follow git tags, newest first; commits after the latest tag land
 * under "Unreleased". Run `npm version ...` first so a release has its tag.
 * The file is auto-generated — edit commit messages, not CHANGELOG.md.
 */
import { execFileSync } from "node:child_process";
import { readFileSync, writeFileSync } from "node:fs";

const git = (...args) => execFileSync("git", args, { encoding: "utf8" }).trim();

const CATEGORIES = [
  ["Features", /^feat(\(|:)/i],
  ["Fixes", /^fix(\(|:)/i],
  ["Documentation", /^docs(\(|:)/i],
  ["CI & build", /^(ci|build)(\(|:)/i],
  ["Refactors", /^refactor(\(|:)/i],
  ["Tests", /^test(\(|:)/i],
  ["Maintenance", /^(chore|perf|style|revert)(\(|:)/i],
];

function sectionBody(range) {
  const args = ["log", "--no-merges", "--pretty=format:%s"];
  if (range) args.push(range);
  const log = git(...args);
  if (!log) return "";

  const buckets = new Map([...CATEGORIES.map(([label]) => [label, []]), ["Other", []]]);
  for (const subject of log.split("\n")) {
    const label = CATEGORIES.find(([, re]) => re.test(subject))?.[0] ?? "Other";
    buckets.get(label).push(subject);
  }

  const lines = [];
  for (const [label, items] of buckets) {
    if (items.length === 0) continue;
    lines.push(`**${label}**`, ...items.map((item) => `- ${item}`), "");
  }
  return lines.join("\n").trimEnd();
}

const pkg = JSON.parse(readFileSync(new URL("../package.json", import.meta.url), "utf8"));
const tagOutput = git("tag", "--sort=-v:refname");
const tags = tagOutput ? tagOutput.split("\n").filter(Boolean) : [];

const sections = [];

const head = sectionBody(tags.length ? `${tags[0]}..HEAD` : "");
if (head) {
  const title = tags.length ? "Unreleased" : `Unreleased (current version v${pkg.version})`;
  sections.push([title, "", head]);
}

for (let i = 0; i < tags.length; i++) {
  const range = i + 1 < tags.length ? `${tags[i + 1]}..${tags[i]}` : tags[i];
  const body = sectionBody(range);
  if (!body) continue;
  const date = git("log", "-1", "--format=%cs", tags[i]);
  sections.push([tags[i], date, body]);
}

const lines = [
  "# Changelog",
  "",
  "Auto-generated by `npm run changelog` — do not edit by hand.",
  "",
];
for (const [title, date, body] of sections) {
  lines.push(`## ${title}${date ? ` — ${date}` : ""}`, "", body, "");
}
if (sections.length === 0) lines.push("_No commits yet._", "");

writeFileSync(new URL("../CHANGELOG.md", import.meta.url), lines.join("\n"), "utf8");
console.log(`CHANGELOG.md updated — ${sections.length} section(s).`);
